/**
 * Switches the active research tab
 */
function switchTab(tab, container) {
  activeResearchTab = tab;

  // Update button active styles
  container.querySelectorAll(".research-tab-btn").forEach((btn) => {
    if (btn.getAttribute("data-tab") === tab) {
      btn.style.background = "#a855f7";
      btn.style.color = "#ffffff";
      btn.style.borderColor = "#a855f7";
    } else {
      btn.style.background = "var(--bg-card)";
      btn.style.color = "var(--text-muted)";
      btn.style.borderColor = "var(--border-color)";
    }
  });

  const contentEl = document.getElementById("research-tab-content");
  if (!contentEl) return;

  if (tab === "overview") {
    renderOverviewTab(contentEl);
  } else if (tab === "baselines") {
    renderBaselinesTab(contentEl);
  } else if (tab === "adversarial") {
    renderAdversarialTab(contentEl);
  } else if (tab === "realdas") {
    renderRealDasTab(contentEl);
  } else if (tab === "provenance") {
    renderProvenanceTab(contentEl);
  }
}

